// NODE 1: INPUT VALIDATION
// Outputs 3 core objects: reference_case_text, case_study_context, generated_case

const body = $input.first().json.body || {};

// Only these fields are truly required
const required = ['reference_case_url', 'client_name', 'industry', 'behaviors', 'target_level'];
const missing = required.filter(f => !body[f]);

if (missing.length > 0) {
  return [{
    json: {
      status: 'error',
      error_type: 'validation_error',
      error_message: `Missing required fields: ${missing.join(', ')}`,
      missing_fields: missing
    }
  }];
}

// Validate reference_case_url format
const driveUrl = body.reference_case_url;
if (!driveUrl || !driveUrl.match(/^https:\/\/(drive|docs)\.google\.com\//)) {
  return [{
    json: {
      status: 'error',
      error_type: 'validation_error',
      error_message: 'Invalid Google Drive URL format',
      received_url: driveUrl
    }
  }];
}

// Validate target_level
const validLevels = ['Low', 'Mid', 'High', 'Exceptional'];
if (!validLevels.includes(body.target_level)) {
  return [{
    json: {
      status: 'error',
      error_type: 'validation_error',
      error_message: `Invalid target_level. Must be one of: ${validLevels.join(', ')}`,
      received: body.target_level
    }
  }];
}

// Validate behaviors structure
const behaviors = body.behaviors;
if (!behaviors || typeof behaviors !== 'object') {
  return [{
    json: {
      status: 'error',
      error_type: 'validation_error',
      error_message: 'behaviors object is missing or invalid'
    }
  }];
}

const totalCount = behaviors.total_count;
if (!totalCount || totalCount < 6 || totalCount > 15) {
  return [{
    json: {
      status: 'error',
      error_type: 'validation_error',
      error_message: 'behaviors.total_count must be between 6 and 15',
      received: totalCount
    }
  }];
}

// All validations passed - return 3 core objects
return [{
  json: {
    status: 'validated',
    google_drive_file_url: driveUrl,
    // Core Object 1: Will be populated after extraction
    reference_case_text: null,
    // Core Object 2: case_study_context (user inputs)
    case_study_context: {
      // Required fields
      client_name: body.client_name,
      industry: body.industry,
      target_level: body.target_level,
      behaviors: behaviors,
      // Optional fields (pass through if present)
      project_summary: body.project_summary || body.project_background || '',
      designation: body.designation || null,
      departments: body.departments || [],
      business_function: body.business_function || null,
      number_of_questions: body.number_of_questions || 3,
      user_instruction: body.user_instruction || body.special_instructions || '',
      // Workflow identifiers
      workflow_session_id: body.workflow_session_id || `session_${Date.now()}`,
      workflow_id: body.workflow_id || 'case_study_modification',
      project_id: body.project_id || 'project_default',
      client_id: body.client_id || 'client_default'
    },
    // Core Object 3: Will accumulate generated content
    generated_case: {}
  }
}];

// Validate extraction and output 3 core objects
const subWorkflowResult = $input.first().json;
const originalInput = $('1.2_VAL_Input').first().json;

const validationErrors = [];

if (subWorkflowResult.status !== 'ok') {
  validationErrors.push(`Sub-workflow status is "${subWorkflowResult.status}", expected "ok"`);
}

if (Array.isArray(subWorkflowResult.errors) && subWorkflowResult.errors.length > 0) {
  validationErrors.push(`Sub-workflow returned errors: ${JSON.stringify(subWorkflowResult.errors)}`);
}

if (!subWorkflowResult.data || typeof subWorkflowResult.data !== 'object') {
  validationErrors.push('Sub-workflow data object is missing or invalid');
}

const extractedText = subWorkflowResult.data?.extracted_text;
if (!extractedText || typeof extractedText !== 'string' || extractedText.trim() === '') {
  validationErrors.push('Extracted text is missing or empty');
}

const charCount = subWorkflowResult.data?.char_count || 0;
if (charCount < 100) {
  validationErrors.push(`Extracted text too short (${charCount} chars)`);
}

if (validationErrors.length > 0) {
  return [{
    json: {
      status: 'extraction_failed',
      error_type: 'extraction_validation_error',
      error_message: validationErrors.join(' | '),
      validation_errors: validationErrors,
      sub_workflow_output: subWorkflowResult
    }
  }];
}

// Return 3 core objects with populated reference_case_text
return [{
  json: {
    status: 'extraction_validated',
    // Core Object 1: Extracted text
    reference_case_text: extractedText,
    // Core Object 2: User context (unchanged)
    case_study_context: originalInput.case_study_context,
    // Core Object 3: Empty, will be filled by LLM nodes
    generated_case: {},
    // Metadata
    extraction_metadata: {
      source_url: subWorkflowResult.data.source_url,
      mimeType: subWorkflowResult.data.mimeType,
      file_name: subWorkflowResult.data.file_name,
      extraction_method: subWorkflowResult.data.extraction_method,
      char_count: charCount
    }
  }
}];

// MERGE Node 2: Update case_study_context with LLM response
const llmResult = $input.first().json;
const coreObjects = $('1.6_VAL_Extraction').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 2 LLM response missing');
}

// Node 2 returns consolidated case_study_context
return [{
  json: {
    reference_case_text: coreObjects.reference_case_text,
    case_study_context: llmResult.llm_response,
    generated_case: coreObjects.generated_case,
    extraction_metadata: coreObjects.extraction_metadata
  }
}];

// MERGE Node 3: Add parsed_reference to generated_case
const llmResult = $input.first().json;
const prev = $('2.3_MRG_Context').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 3 LLM response missing');
}

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      parsed_reference: llmResult.llm_response.parsed_reference || llmResult.llm_response
    },
    extraction_metadata: prev.extraction_metadata
  }
}];

// FORMAT Node 4: Build prompt for industry transformation (V2)
const input = $input.first().json;
const ctx = input.case_study_context;
const genCase = input.generated_case;

const parsedRef = genCase.parsed_reference || genCase.parsed_reference_case;
const constraints = ctx.case_design_constraints || ctx;

const prompt = `You are an industry context adaptation specialist. Transform the reference case to authentically reflect the new client and industry while preserving narrative integrity.

## REFERENCE CASE STRUCTURE
${JSON.stringify(parsedRef, null, 2)}

## CASE CONTEXT
- Target Industry: ${constraints.industry || ctx.industry}
- Target Company: ${constraints.client_name || ctx.client_name}
- Target Level: ${constraints.target_level || ctx.target_level}
- Language Difficulty: ${constraints.language_difficulty || 'professional'}
- Strategic Context Points: ${JSON.stringify(constraints.strategic_context_points || [])}
- Departments: ${JSON.stringify(constraints.departments || [])}

## USER INSTRUCTION (if provided)
${constraints.user_instruction || 'None'}

CRITICAL: If user_instruction indicates "just change industry context" or "minimal modification":
- Preserve ALL situations and scenarios exactly
- ONLY change company name, industry terminology, and role titles
- Do NOT restructure or reimagine challenges
- Keep metric VALUES the same, only change LABELS where needed

If user_instruction is blank or requests more substantial changes:
- Proceed with full intelligent adaptation

## ADAPTATION RULES

### 1. Company & Industry Transformation
Replace systematically:
- Company name: ${parsedRef?.original_context?.company || 'Original'} → ${constraints.client_name || ctx.client_name}
- Industry context: ${parsedRef?.original_context?.industry || 'Original'} → ${constraints.industry || ctx.industry}

Adapt intelligently:
- Job titles to match industry norms (e.g., "Plant Manager" in manufacturing vs "Branch Manager" in banking)
- Technical terminology specific to industry
- Metrics units (e.g., "units shipped" → "tons processed" → "policies issued")
- Department names if they differ

### 2. Strategic Context Weaving
From project_summary and strategic_context_points:
${JSON.stringify(constraints.strategic_context_points || [])}

DO NOT just find-replace. Strategically integrate:
- Identify 2-3 natural insertion points in the narrative
- Weave context so it feels ORGANIC, not bolted-on
- Use context to add AUTHENTICITY without adding COMPLEXITY
- Ensure woven elements don't bloat word count significantly

### 3. Preserve What Works
KEEP UNCHANGED:
- Narrative structure and flow
- Cause-effect relationships
- Emotional beats and tension points
- Metric VALUES (percentages, timeframes) - only change units/labels
- Human dynamics and relationship patterns
- Protagonist personality and approach

### 4. Adapt Data/Tables
For each table flagged in parsed_reference_case:
- If marked ESSENTIAL: adapt terminology but keep structure and values
- If marked DECORATIVE: consider simplifying or removing
- Ensure all data labels match new industry context
- Verify numbers still make sense in new context

### 5. Name Adaptation
- Protagonist: Keep original OR generate culturally appropriate alternative for client's region
- Team members: Adapt names if they seem culturally mismatched
- Ensure names match the geographic/cultural context of ${constraints.client_name || ctx.client_name}

### 6. Department Relevance
If departments are specified: ${JSON.stringify(constraints.departments || [])}
- Ensure scenarios feel relevant to these departments
- Adjust functional context if needed

## QUALITY CHECK BEFORE OUTPUT
□ Every paragraph authentically reflects ${constraints.industry || ctx.industry}?
□ No leftover references to original industry/company?
□ Strategic context points feel naturally integrated?
□ Someone from ${constraints.client_name || ctx.client_name} would recognize this as realistic?
□ Word counts haven't bloated significantly?

## OUTPUT REQUIREMENTS
Return simplified JSON with adapted content only:

{
  "industry_adapted_case": {
    "situation": {"content": "string"},
    "introduction": {"content": "string", "protagonist_name": "string", "protagonist_role": "string"},
    "challenges": [{"number": 1, "title": "string", "content": "string"}]
  }
}`;

return [{ json: {
  prompt: prompt,
  model: 'global.anthropic.claude-sonnet-4-5-20250929-v1:0',
  node_name: 'Node4_Industry_Transform',
  workflow_session_id: ctx.workflow_session_id,
  workflow_id: ctx.workflow_id,
  project_id: ctx.project_id,
  client_id: ctx.client_id
}}];

// MERGE Node 4: Add industry_adapted to generated_case
const llmResult = $input.first().json;
const prev = $('3.3_MRG_ParseRef').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 4 LLM response missing');
}

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      industry_adapted: llmResult.llm_response.industry_adapted || llmResult.llm_response
    },
    extraction_metadata: prev.extraction_metadata
  }
}];

// MERGE Node 5: Add challenge_outlines to generated_case (V3 - simplified)
const llmResult = $input.first().json;
const prev = $('4.3_MRG_Industry').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 5 LLM response missing');
}

const response = llmResult.llm_response;

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      behavior_mapping: { challenge_outlines: response.challenge_outlines || [] }
    },
    extraction_metadata: prev.extraction_metadata
  }
}];

// MERGE Node 6: Add challenges to generated_case (V3 - simplified)
const llmResult = $input.first().json;
const prev = $('5.3_MRG_Behavior').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 6 LLM response missing');
}

const response = llmResult.llm_response;

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      final_challenges: response.challenges || response.final_challenges,
      situation_section: { content: response.situation },
      introduction_section: {
        content: response.introduction,
        protagonist_name: response.protagonist_name,
        protagonist_role: response.protagonist_role
      }
    },
    extraction_metadata: prev.extraction_metadata
  }
}];

// MERGE Node 7: Add questions and assessor guidance (V3 - simplified)
const llmResult = $input.first().json;
const prev = $('6.3_MRG_Challenge').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 7 LLM response missing');
}

const response = llmResult.llm_response;

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      assessment_questions: response.questions || response.assessment_questions,
      assessor_guidance: response.assessor_guidance
    },
    extraction_metadata: prev.extraction_metadata
  }
}];

// MERGE Node 8: Add quality_scores and content (V3 - simplified)
const llmResult = $input.first().json;
const prev = $('7.3_MRG_Questions').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 8 LLM response missing');
}

const response = llmResult.llm_response;
const qualityScores = response.quality_scores || {};

// Calculate average score from 16 criteria
const scores = Object.values(qualityScores)
  .map(q => q?.score)
  .filter(s => typeof s === 'number');
const avgScore = scores.length > 0 ? scores.reduce((a, b) => a + b, 0) / scores.length : 0;

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      quality_passed: response.quality_passed !== false,
      quality_scores: qualityScores,
      issues_fixed: response.issues_fixed || [],
      quality_assured_content: response.content || {}
    },
    extraction_metadata: prev.extraction_metadata,
    quality_rating: avgScore,
    overall_pass: response.quality_passed !== false
  }
}];

// FORMAT Node 9: Build prompt for bias check (V3 - diff-based output to prevent truncation)
const input = $input.first().json;
const ctx = input.case_study_context;
const genCase = input.generated_case;

const constraints = ctx.case_design_constraints || ctx;
const qualityContent = genCase.quality_assured_content || {};
const challenges = qualityContent.challenges || genCase.final_challenges || genCase.challenges || [];
const questions = qualityContent.questions || genCase.assessment_questions || [];
const guidance = qualityContent.assessor_guidance || genCase.assessor_guidance || {};

const prompt = `You are a bias detection specialist. Screen content for potential biases.

## CONTENT TO REVIEW
- Situation: ${qualityContent.situation || genCase.situation_section?.content || ''}
- Introduction: ${qualityContent.introduction || genCase.introduction_section?.content || ''}
- Challenges: ${JSON.stringify(challenges, null, 2)}
- Questions: ${JSON.stringify(questions, null, 2)}
- Guidance: ${JSON.stringify(guidance, null, 2)}

## CONTEXT
- Target Level: ${constraints.target_level || ctx.target_level}
- Industry: ${constraints.industry || ctx.industry}

## BIAS CATEGORIES
Evaluate for: Gender, Cultural, Age, Socioeconomic, Disability, Language Complexity

For each category check for:
- Stereotyping or role assumptions
- Biased language (e.g., "manpower", "chairman", ableist terms)
- Cultural/socioeconomic assumptions
- Unnecessary complexity disadvantaging non-native speakers

Severity levels: none | low | medium | high

## CRITICAL OUTPUT REQUIREMENT
DO NOT return the full content. Instead, return ONLY:
1. Pass/fail status
2. High severity issue count
3. A modifications array with find/replace entries for any fixes needed

This prevents output truncation.

## OUTPUT FORMAT
Return valid JSON only:
{
  "bias_passed": true | false,
  "high_severity_issues": number,
  "modifications": [
    {
      "location": "challenges[0].content | questions[1].text | situation | introduction | guidance.overall",
      "find": "exact text to find",
      "replace": "replacement text"
    }
  ]
}

If no issues found, return:
{
  "bias_passed": true,
  "high_severity_issues": 0,
  "modifications": []
}`;

return [{ json: {
  prompt: prompt,
  model: 'global.anthropic.claude-haiku-4-5-20251001-v1:0',
  node_name: 'Node9_Bias_Check',
  workflow_session_id: ctx.workflow_session_id,
  workflow_id: ctx.workflow_id,
  project_id: ctx.project_id,
  client_id: ctx.client_id
}}];

// MERGE Node 9: Apply bias modifications to content (V3 - diff-based)
const llmResult = $input.first().json;
const prev = $('8.3_MRG_Quality').first().json;

if (!llmResult.llm_response) {
  throw new Error('Node 9 LLM response missing');
}

const response = llmResult.llm_response;
const modifications = response.modifications || [];

// Get content from quality_assured_content or fallback
const genCase = prev.generated_case || {};
const qualityContent = genCase.quality_assured_content || {};
let situation = qualityContent.situation || genCase.situation_section?.content || '';
let introduction = qualityContent.introduction || genCase.introduction_section?.content || '';
let challenges = JSON.parse(JSON.stringify(qualityContent.challenges || genCase.final_challenges || []));
let questions = JSON.parse(JSON.stringify(qualityContent.questions || genCase.assessment_questions || []));
let guidance = JSON.parse(JSON.stringify(qualityContent.assessor_guidance || genCase.assessor_guidance || {}));

// Apply each modification
for (const mod of modifications) {
  const { location, find, replace } = mod;
  if (!find || !replace) continue;

  if (location === 'situation') {
    situation = situation.replace(find, replace);
  } else if (location === 'introduction') {
    introduction = introduction.replace(find, replace);
  } else if (location === 'guidance.overall') {
    if (guidance.overall) guidance.overall = guidance.overall.replace(find, replace);
  } else if (location.startsWith('challenges[')) {
    const match = location.match(/challenges\[(\d+)\]\.(\w+)/);
    if (match) {
      const idx = parseInt(match[1]);
      const field = match[2];
      if (challenges[idx] && challenges[idx][field]) {
        challenges[idx][field] = challenges[idx][field].replace(find, replace);
      }
    }
  } else if (location.startsWith('questions[')) {
    const match = location.match(/questions\[(\d+)\]\.(\w+)/);
    if (match) {
      const idx = parseInt(match[1]);
      const field = match[2];
      if (questions[idx] && questions[idx][field]) {
        questions[idx][field] = questions[idx][field].replace(find, replace);
      }
    }
  }
}

return [{
  json: {
    reference_case_text: prev.reference_case_text,
    case_study_context: prev.case_study_context,
    generated_case: {
      ...prev.generated_case,
      bias_passed: response.bias_passed !== false,
      high_severity_issues: response.high_severity_issues || 0,
      bias_modifications_applied: modifications.length,
      // Store final content after bias fixes
      final_content: {
        situation: situation,
        introduction: introduction,
        challenges: challenges,
        questions: questions,
        assessor_guidance: guidance
      }
    },
    extraction_metadata: prev.extraction_metadata,
    passed_bias_check: response.bias_passed !== false && (response.high_severity_issues || 0) === 0
  }
}];

// Stage 10: Final Packaging - Pure JavaScript (no LLM)
// Assembles final_output from generated_case with case_study_context

const prev = $input.first().json;
const genCase = prev.generated_case || {};
const ctx = prev.case_study_context || {};
const constraints = ctx.case_design_constraints || ctx;

// Get content from final_content (V3 bias output) or fallback chain
const content = genCase.final_content || genCase.quality_assured_content || {};
const challenges = content.challenges || genCase.final_challenges || genCase.challenges || [];
const questions = content.questions || genCase.assessment_questions || [];
const assessorGuidance = content.assessor_guidance || genCase.assessor_guidance || {};
const situation = content.situation || genCase.situation_section?.content || genCase.situation_section || '';
const introduction = content.introduction || genCase.introduction_section?.content || genCase.introduction_section || '';

// Calculate total word count for case_length
const totalWords = challenges.reduce((sum, c) => sum + (c.word_count || c.content?.split(/\s+/).length || 175), 0);
const caseLength = totalWords < 600 ? 'short' : totalWords > 900 ? 'long' : 'medium';

// Generate professional title
const industry = constraints.industry || ctx.industry || 'Business';
const firstChallengeTitle = challenges[0]?.title || 'Strategic Decision Making';
const title = industry + ' Leadership Case: ' + firstChallengeTitle.replace(/^Challenge \d+:\s*/i, '');

// Calculate quality summary from quality_scores
const qualityScores = genCase.quality_scores || {};
const scoreValues = qualityScores.scores || qualityScores;
const allScores = Object.entries(scoreValues)
  .filter(([k, v]) => typeof v === 'number' && !k.includes('average') && !k.includes('overall'))
  .map(([k, v]) => v);
const overallRating = allScores.length > 0 ? Math.min(...allScores) : 8;
const avgRating = allScores.length > 0 ? allScores.reduce((a, b) => a + b, 0) / allScores.length : 8;
const passedChecks = allScores.filter(s => s >= 8).length;

// Behavior coverage from mapping
const behaviorMapping = genCase.behavior_mapping || {};
const behaviorsList = (behaviorMapping.behaviors || behaviorMapping.mapped_behaviors || [])
  .map(b => typeof b === 'string' ? b : b.name || b.behavior_name)
  .filter(Boolean);

// Bias check results (V3 format)
const passedBias = genCase.bias_passed !== false && (genCase.high_severity_issues || 0) === 0;

// Build coverage distribution by challenge
const distribution = {};
challenges.forEach((c, i) => {
  const behaviors = (c.behaviors_assessed || []).map(b => typeof b === 'string' ? b : b.name).filter(Boolean);
  distribution['challenge_' + (i + 1)] = behaviors;
});

// Generate recommendations based on target level
const targetLevel = constraints.target_level || 'Mid';
const recommendations = [];
if (targetLevel === 'Low') {
  recommendations.push('Suitable for entry-level candidates with 0-2 years experience');
  recommendations.push('Allow additional time for candidates to process information');
} else if (targetLevel === 'Mid') {
  recommendations.push('Appropriate for mid-level candidates with 3-7 years experience');
  recommendations.push('Expect balanced responses showing both analytical and people skills');
} else if (targetLevel === 'High') {
  recommendations.push('Designed for senior candidates with 8+ years experience');
  recommendations.push('Look for strategic thinking and enterprise-level considerations');
} else if (targetLevel === 'Exceptional') {
  recommendations.push('Reserved for executive-level assessment');
  recommendations.push('Expect sophisticated multi-stakeholder analysis and visionary solutions');
}
if (!passedBias) {
  recommendations.push('Review bias check notes before deployment');
}

// Assemble final_output (what goes to API)
const final_output = {
  case_study_metadata: {
    title: title,
    created_at: new Date().toISOString(),
    version: '1.0',
    case_length: caseLength
  },
  case_study_context: {
    workflow_session_id: ctx.workflow_session_id,
    workflow_id: ctx.workflow_id,
    project_id: ctx.project_id,
    client_id: ctx.client_id,
    case_design_constraints: constraints
  },
  case_study_content: {
    introduction: (situation + '\n\n' + introduction).trim(),
    challenges: challenges
  },
  assessment_questions: questions,
  assessor_guidance: assessorGuidance,
  quality_summary: {
    overall_rating: Math.round(overallRating * 10) / 10,
    average_rating: Math.round(avgRating * 10) / 10,
    total_checks_passed: passedChecks,
    total_checks_conducted: 16,
    passed_quality_check: overallRating >= 8,
    passed_bias_check: passedBias,
    total_behaviors_covered: behaviorsList.length,
    unique_behaviors: behaviorsList.length,
    behaviors_list: behaviorsList,
    behavior_coverage_analysis: {
      coverage_percentage: '100%',
      distribution: distribution
    },
    recommendations_for_deployment: recommendations
  }
};

return [{
  json: {
    status: 'success',
    final_output: final_output,
    // Keep generated_case as internal trace
    generated_case: genCase,
    reference_case_text: prev.reference_case_text,
    extraction_metadata: prev.extraction_metadata,
    delivery_ready: true
  }
}];

// NODE 1: INPUT VALIDATION
// Outputs 3 core objects: reference_case_text, case_study_context, generated_case

const body = $input.first().json.body || {};

// Only these fields are truly required
const required = ['reference_case_url', 'client_name', 'industry', 'behaviors', 'target_level'];
const missing = required.filter(f => !body[f]);

if (missing.length > 0) {
  return [{
    json: {
      status: 'error',
      error_type: 'validation_error',
      error_message: `Missing required fields: ${missing.join(', ')}`,
      missing_fields: missing
    }
  }];
}

// Validate reference_case_url format
const driveUrl = body.reference_case_url;
if (!driveUrl || !driveUrl.match(/^https:\/\/(drive|docs)\.google\.com\//)) {
