  const { location, find, replace } = mod;
  if (!find || !replace) continue;

  if (location === 'situation') {
    situation = situation.replace(find, replace);
  } else if (location === 'introduction') {
    introduction = introduction.replace(find, replace);
  } else if (location === 'guidance.overall') {
    if (guidance.overall) guidance.overall = guidance.overall.replace(find, replace);
  } else if (location.startsWith('challenges[')) {
    const match = location.match(/challenges\[(\d+)\]\.(\w+)/);
    if (match) {
      const idx = parseInt(match[1]);
      const field = match[2];
      if (challenges[idx] && challenges[idx][field]) {
        challenges[idx][field] = challenges[idx][field].replace(find, replace);
      }
    }
  } else if (location.startsWith('questions[')) {
    const match = location.match(/questions\[(\d+)\]\.(\w+)/);
    if (match) {
      const idx = parseInt(match[1]);
      const field = match[2];
      if (questions[idx] && questions[idx][field]) {
        questions[idx][field] = questions[idx][field].replace(find, replace);
      }
    }
  }
